import json, os, glob

def load(path):
    d = {}
    for i in glob.glob(path + "/*.log"):
        d=os.path.basename(path); 
    return

# Summaries per run: group rows by phase, fg only
def summarize(run_dir):
    f = os.path.join(run_dir, "requests.jsonl")
    rows = [json.loads(l) for l in open(f) if l.strip()]
    print(f"\n=== {run_dir} ===")
    print("total rows:", len(rows))
    for phase in ["single-agent","single-mem","dual-agent","dual-mem"]:
        fg = [r for r in rows if r["fg_bg"]=="fg" and r["phase"]==phase]
        bg = [r for r in rows if r["fg_bg"]=="bg" and r["phase"]==phase]
        lrow = [r for r in rows if r["fg_bg"]=="fg" and r["phase"]==phase and r.get("finish_reason")=="length"]
        def tok(rows): 
            return sum(r.get("predicted_n") or 0 for r in rows)
        def ms(rows):
            return sum(r.get("predicted_ms") or 0 for r in rows)
        def ok(rows): return sum(1 for r in rows if "error" not in r)
        t = tok(fg); m = ms(fg)
        l_t = tok(lrow); l_m = ms(lrow)
        t_no = t - l_t; m_no = m - l_m
        fps = (t/m*1000) if m>0 else 0
        fps_no = (t_no/m_no*1000) if m_no>0 else 0
        print(f"  {phase:14s} fg={len(fg)} bg={len(bg)} err={sum(1 for r in fg if 'error' in r)}")
        print(f"     fg sum_pred={t} sum_ms={m:.0f} -> {fps:7.2f} t/s ; no-length {t_no} {m_no:.0f} -> {fps_no:7.2f} t/s ; length rows={len(lrow)}")
        # per-phase identical share we need off as ref; skip here
    # length rows detail
    print("  length rows (fg):")
    for r in rows:
        if r["fg_bg"]=="fg" and r.get("finish_reason")=="length":
            print(f"     {r['phase']:14s} {r['role']} {r['id']:28s} pred_n={r['predicted_n']} max={r['max_tokens']}")

for d in sorted(glob.glob("*/")):
    if d.endswith("replay/") and d.startswith("./"): pass
    dd = d.rstrip("/")
    if os.path.exists(os.path.join(os.getcwd(), dd, "requests.jsonl")):
        summarize(os.path.join(os.getcwd(), dd))
