#!/usr/bin/env python3
"""Summarize M1 n-gram spec replay results (off vs A vs B, greedy/prod).

Usage:
    python3 bench/analyze_spec_replay.py <run-dir>
where <run-dir> contains the per-(label-sampling) subdirs (e.g. off-greedy, A-greedy,
A-prod). Prints, per run and phase:
  - fg sum(predicted_n)/sum(predicted_ms)  t/s, WITH and WITHOUT length rows
  - count and ids of fg finish_reason==length rows
  - combined (fg+bg) throughput over the whole phase (sum pred_n / sum predicted_ms)
  - for the spec runs, draft_n/draft_n_accepted totals
  - per-phase output-identity share vs off (same phase, fg rows)
"""
import json
import os
import sys

def load_rows(d):
    out = {}
    p = os.path.join(d, "requests.jsonl")
    if not os.path.exists(p):
        return out
    for ln in open(p):
        ln = ln.strip()
        if not ln:
            continue
        r = json.loads(ln)
        out[(r["phase"], r["id"], r["fg_bg"])] = r
    return out

PHASES = ["single-agent", "single-mem", "dual-agent", "dual-mem"]

def fps(t, m):
    return (t / m * 1000.0) if m > 0 else 0.0

def phase_stats(rows, phase):
    fg = [r for r in rows.values() if r["phase"] == phase and r["fg_bg"] == "fg"]
    bg = [r for r in rows.values() if r["phase"] == phase and r["fg_bg"] == "bg"]
    def tok(lst):
        return sum(r.get("predicted_n") or 0 for r in lst)
    def ms(lst):
        return sum(r.get("predicted_ms") or 0 for r in lst)
    lrow = [r for r in fg if r.get("finish_reason") == "length"]
    t, m = tok(fg), ms(fg)
    lt, lm = tok(lrow), ms(lrow)
    tn, mn = t - lt, m - lm
    comb = fps(tok(fg + bg), ms(fg + bg))
    return {
        "fg": len(fg), "bg": len(bg), "err": sum(1 for r in fg if "error" in r),
        "fps": fps(t, m), "fps_no": fps(tn, mn),
        "length": [(r["id"], r.get("predicted_n")) for r in lrow],
        "comb": comb,
    }

def main():
    root = sys.argv[1]
    runs = sorted(d for d in os.listdir(root)
                  if os.path.isdir(os.path.join(root, d))
                  and os.path.exists(os.path.join(root, d, "requests.jsonl")))
    off_key = next((d for d in runs if d.startswith("off-")), runs[0])
    loaded = {d: load_rows(os.path.join(root, d)) for d in runs}

    print("== per-run phase summary ==")
    for d in runs:
        rows = loaded[d]
        print(f"\n--- {d} (off? {d == off_key}) ---")
        for p in PHASES:
            s = phase_stats(rows, p)
            length_str = "; ".join(f"{i}(pred={n})" for i, n in s["length"]) or "-"
            print(f"  {p:14s} fg={s['fg']:2d} bg={s['bg']:2d} err={s['err']} "
                  f"fg={s['fps']:7.2f} t/s  no-length={s['fps_no']:7.2f} t/s  "
                  f"combined(fg+bg)={s['comb']:7.2f} t/s  length: {length_str}")

    print("\n== draft totals (fg rows) ==")
    for d in runs:
        if d.startswith("off-"):
            continue
        rows = loaded[d]
        fg = [r for r in rows.values() if r["fg_bg"] == "fg"]
        tn = sum(r.get("draft_n", 0) for r in fg)
        ac = sum(r.get("draft_n_accepted", 0) for r in fg)
        print(f"  {d}: draft_n={tn} draft_n_accepted={ac} "
              f"(accept {ac / max(tn, 1) * 100:.1f}%) over {len(fg)} fg rows")

    print("\n== fg output identity per phase vs off (same phase+id) ==")
    off = loaded[off_key]
    for d in runs:
        if d == off_key:
            continue
        rows = loaded[d]
        for p in PHASES:
            ids = sorted({i for (ph, i, gb) in off
                          if off[(ph, i, gb)]["fg_bg"] == "fg" and ph == p})
            same = 0
            for i in ids:
                k = (p, i, "fg")
                if k in rows and off[k]["out_sha256"] == rows[k]["out_sha256"]:
                    same += 1
            print(f"  {d}: {p:14s} identical={same}/{len(ids)}")

if __name__ == "__main__":
    main()

